INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(93236220, 'World Legacy Clash', '围绕星遗物的战争', '星遺物を巡る戦い', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上1只表侧表示怪兽直到结束阶段除外，以对方场上1只表侧表示怪兽为对象才能发动。那只对方怪兽的攻击力·守备力下降因为这张卡发动而除外的怪兽的各自原本数值。'),
(73192600, 'World Legacy Cliffhanger', '星遗物之对焉', '星遺物の対焉', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：连接怪兽之间进行战斗的攻击宣言时才能发动。双方的场上·墓地的怪兽全部回到持有者卡组。这张卡发动过的回合，双方不能连接召唤。'),
(36197902, 'World Legacy Collapse', '星遗物带来的崩界', '星遺物の齎す崩界', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地以及自己场上的表侧表示怪兽之中把1只「星遗物」怪兽除外，以场上1只连接怪兽为对象才能发动。那只怪兽的攻击力上升除外的怪兽的原本攻击力数值。 ②：这张卡在墓地存在的状态，自己场上的连接怪兽被战斗或者对方的效果破坏的场合，把这张卡除外才能发动。从自己墓地选1只电子界族连接怪兽特殊召唤。'),
(61654098, 'World Legacy Discovery', '与星遗物的邂逅', '星遺物との邂逅', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「星杯」怪兽的攻击力·守备力上升300。 ②：1回合1次，自己场上的表侧表示的「星杯」怪兽因对方的效果从场上离开的场合或者被战斗破坏的场合，以自己墓地1只「星杯」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(87571563, 'World Legacy Guardragon', '星遗物守护龙', '星遺物の守護竜', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡的发动时，可以以自己墓地1只4星以下的龙族怪兽为对象。那个场合，那只怪兽加入手卡或特殊召唤。 ②：1回合1次，以自己场上1只龙族怪兽为对象才能发动。那只自己怪兽的位置向其他的自己的主要怪兽区域移动。'),
(35183584, 'World Legacy Guardragon Mardark', '星遗物守护龙 黑之米罗达克', '星遺物の守護竜メロダーク', 'Effect Monster', 'Dragon', 'WIND', 9, 2600, 3000, '这个卡名的①③的效果1回合各能使用1次。 ①：从自己的手卡·墓地把2只通常怪兽除外才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，对方场上的怪兽的攻击力·守备力下降自己场上的龙族怪兽数量×500。 ③：场上的这张卡被战斗·效果破坏的场合才能发动。从自己墓地选和这张卡是原本的种族·属性不同的1只9星怪兽加入手卡。'),
(67831115, 'World Legacy in Shadow', '投在星遗物上的阴影', '星遺物に差す影', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「机怪虫」怪兽的攻击力·守备力上升300。 ②：1回合1次，自己主要阶段才能发动。从手卡把1只2星以下的昆虫族怪兽表侧守备表示或者里侧守备表示特殊召唤。 ③：自己的反转怪兽被和对方怪兽的战斗破坏时才能发动。那只对方怪兽送去墓地。'),
(2930675, 'World Legacy Key', '到达星遗物的钥匙', '星遺物へ至る鍵', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡的发动时，可以从除外的自己的卡之中以1只「机界骑士」怪兽或者1张「星遗物」卡为对象。那个场合，那张卡加入手卡。 ②：只要自己场上有「机界骑士」怪兽存在，和那怪兽相同纵列发动的对方的陷阱卡的效果无效化。'),
(21254443, 'World Legacy Landmark', '星遗物之引导', '星遺物の導き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡以及自己场上的表侧表示怪兽之中把1只「星遗物」怪兽除外，以自己墓地2只怪兽为对象才能发动。那些怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(14604710, 'World Legacy Monstrosity', '星遗物之胎导', '星遺物の胎導', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从手卡把1只9星怪兽特殊召唤。 ●以自己场上1只9星怪兽为对象才能发动。和那只怪兽是原本的种族·属性不同的2只9星怪兽从卡组特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽不能攻击，结束阶段破坏。'),
(89320376, 'World Legacy Pawns', '星遗物之傀儡', '星遺物の傀儡', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只里侧表示怪兽为对象才能发动。那只怪兽变成表侧攻击表示或者表侧守备表示。 ②：让自己墓地1只「机怪虫」怪兽回到卡组，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(35546670, 'World Legacy Scars', '星遗物所刻印的伤痕', '星遺物が刻む傷痕', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「机界骑士」怪兽的攻击力·守备力上升300。 ②：1回合1次，从手卡丢弃1只「机界骑士」怪兽或者1张「星遗物」卡才能发动。自己从卡组抽1张。 ③：从自己墓地以及自己场上的表侧表示怪兽之中把「机界骑士」怪兽8种类各1只除外才能发动。对方的手卡·额外卡组的卡全部送去墓地。'),
(58374719, 'World Legacy Struggle', '对星遗物的抵抗', '星遺物への抵抗', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以最多有场上的互相连接状态的怪兽数量的场上的魔法·陷阱卡为对象才能发动。那些卡破坏。'),
(99674361, 'World Legacy Succession', '继承星遗物者', '星遺物を継ぐもの', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只怪兽为对象才能发动。那只怪兽在作为场上的连接怪兽所连接区的自己场上特殊召唤。'),
(31706048, 'World Legacy Survivor', '星遗物之醒存', '星遺物の醒存', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己卡组上面把5张卡翻开。那之中有「机怪虫」怪兽或者「星遗物」卡的场合，选那之内的1张加入手卡，剩下的卡全部送去墓地。没有的场合，翻开的卡全部回到卡组。这张卡的发动后，直到回合结束时自己不是连接怪兽不能从额外卡组特殊召唤。'),
(46647145, 'World Legacy Token', '星遗物－星枪－', '星遺物－『星槍』', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(16329071, 'World Legacy Trap Globe', '向星遗物蠢动的陷阱', '星遺物に蠢く罠', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地的卡、自己场上的表侧表示的卡、除外的自己的卡之中选「蠢动于星遗物的陷阱」以外的「星遗物」卡5种类各1张，加入持有者卡组洗切。那之后，自己从卡组抽2张。'),
(62530723, 'World Legacy Whispers', '星遗物之细语', '星遺物の囁き', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡的发动时，可以以场上1只5星以上的怪兽为对象。那个场合，那只怪兽的攻击力·守备力直到回合结束时上升1000。 ②：只要自己场上有「机界骑士」怪兽存在，和那怪兽相同纵列发动的对方的魔法卡的效果无效化。'),
(62279666, 'World Legacy''s Corruption', '星遗物所引导之结果', '星遺物が導く果て', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「星遗物引导的终点」在自己场上只能有1张表侧表示存在。 ②：1回合1次，自己场上的表侧表示的连接怪兽因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。从手卡·卡组把1只「星遗物」怪兽守备表示特殊召唤。'),
(97648103, 'World Legacy''s Heart', '星遗物之加护', '星遺物の加護', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地2只卡名不同的「星杯」怪兽为对象才能发动。那些怪兽加入手卡。 ②：自己场上的连接状态的连接怪兽被战斗破坏的场合，可以作为代替把墓地的这张卡除外。'),
(68191756, 'World Legacy''s Memory', '星遗物之机忆', '星遺物の機憶', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡·卡组把1只「机界骑士」怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到持有者手卡。这张卡的发动后，直到回合结束时自己不是「机界骑士」怪兽不能特殊召唤。'),
(27705190, 'World Legacy''s Mind Meld', '星遗物之交心', '星遺物の交心', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「机怪虫」怪兽存在，对方怪兽的效果发动时才能发动。那个效果变成「选对方场上1只表侧表示怪兽回到持有者手卡」。 ②：把墓地的这张卡除外，以场上1只连接怪兽为对象才能发动。从自己的手卡·卡组·墓地选1只「机怪虫」怪兽在作为成为对象的怪兽所连接区的自己场上里侧守备表示特殊召唤。'),
(25163979, 'World Legacy''s Nightmare', '诱导向星遗物之噩梦', '星遺物へ誘う悪夢', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己的互相连接状态的怪兽的战斗发生的对自己的战斗伤害变成0。 ②：1回合1次，自己主要阶段可以从以下效果选择1个发动。 ●选自己场上1只「幻崩」怪兽，那个位置向其他的自己的主要怪兽区域移动。 ●选自己的主要怪兽区域2只「幻崩」怪兽，那些位置交换。'),
(98935722, 'World Legacy''s Secret', '安眠于星遗物的深层', '星遺物に眠る深層', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡的发动时，可以以自己墓地1只5星以上的怪兽为对象。那个场合，那只怪兽特殊召唤。这张卡从场上离开时那只怪兽破坏。 ②：只要自己场上有「机界骑士」怪兽存在，和那怪兽相同纵列发动的对方怪兽的效果无效化。'),
(85763457, 'World Legacy''s Sorrow', '响彻于星遗物的残叫', '星遺物に響く残叫', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有互相连接状态的怪兽存在，对方把怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(29146185, 'World of Prophecy', '魔导天士 杜勒蒙德', '魔導天士 トールモンド', 'Effect Monster', 'Spellcaster', 'LIGHT', 9, 2900, 2400, '这张卡用魔法师族怪兽或者名字带有「魔导书」的魔法卡的效果特殊召唤成功时，可以选择自己墓地2张名字带有「魔导书」的魔法卡加入手卡。这个效果发动的回合，自己不能把其他怪兽特殊召唤。这个效果把卡加入手卡时，把手卡的名字带有「魔导书」的魔法卡4种类给对方观看才能发动。这张卡以外的场上的卡全部破坏。'),
(5414777, 'World of Spirits', '精灵的世界', '精霊の世界', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②③的效果若非自己场上有7星以上的龙族·光属性同调怪兽存在的场合则不能发动。 ①：作为这张卡的发动时的效果处理，可以从卡组把有「古代妖精龙」的卡名记述的1只怪兽加入手卡。 ②：每次怪兽攻击表示特殊召唤发动。那些怪兽变成守备表示。 ③：自己·对方的结束阶段发动。回合玩家的场上的攻击表示怪兽全部破坏。'),
(42172465, 'World Reassembly', '创星改归', '創星改帰', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡·卡组把1只「星遗物」怪兽特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段破坏。'),
(15079028, 'World Soul - Carbon', '地久神－碳', '地久神－カルボン', 'Effect Monster', 'Fairy', 'EARTH', 4, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把通常召唤的这张卡解放才能发动。从卡组把「地久神-碳素灵」以外的1只天使族·地属性怪兽加入手卡。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的天使族怪兽被送去墓地的场合才能发动。这张卡回到卡组最上面。'),
(12253117, 'World Suppression', '世界平定', '世界の平定', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场地卡发动时才能发动。直到回合结束时场地卡的效果无效。'),
(45112597, 'Worldsea Dragon Zealantis', '世海龙 西兰提斯', '世海龍ジーランティス', 'Link Monster', 'Sea Serpent', 'WATER', NULL, 2500, NULL, '效果怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：「世海龙 西兰提斯」在自己场上只能有1张表侧表示存在。 ②：自己主要阶段才能发动。场上的怪兽全部除外。那之后，这个效果除外的怪兽尽可能在原本持有者的场上表侧表示或里侧守备表示特殊召唤。 ③：自己·对方的战斗阶段才能发动。把最多有场上的互相连接状态的怪兽数量的场上的卡破坏。'),
(88650530, 'Worm Apocalypse', '阿波克立普斯异虫', 'ワーム・アポカリプス', 'Flip Effect Monster', 'Reptile', 'LIGHT', 1, 300, 200, '反转：场上的1张魔法或者陷阱卡破坏。'),
(43140791, 'Worm Bait', '异虫饵', 'ワーム・ベイト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能把3·4星的怪兽召唤·特殊召唤。 ①：自己场上有昆虫族怪兽存在的场合才能发动。在自己场上把2只「虫衍生物」（昆虫族·地·1星·攻/守0）特殊召唤。'),
(15658249, 'Worm Barses', '巴尔萨斯异虫', 'ワーム・バルサス', 'Effect Monster', 'Reptile', 'LIGHT', 3, 1400, 1500, '这张卡召唤成功时，把场上守备表示存在的1只怪兽变成表侧攻击表示。'),
(28506708, 'Worm Call', '异虫呼唤', 'ワーム・コール', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，可以从手卡把1只名字带有「异虫」的爬虫类族怪兽里侧守备表示特殊召唤。这个效果1回合只能使用1次。'),
(51043243, 'Worm Cartaros', '卡尔塔罗斯异虫', 'ワーム・カルタロス', 'Flip Effect Monster', 'Reptile', 'LIGHT', 4, 1200, 500, '反转：从自己卡组把1只4星以下的名字带有「异虫」的爬虫类族怪兽加入手卡。'),
(88438982, 'Worm Dimikles', '迪米克雷斯异虫', 'ワーム・ディミクレス', 'Flip Effect Monster', 'Reptile', 'LIGHT', 4, 1700, 1400, '反转：只要这张卡在场上表侧表示存在，这张卡的攻击力·守备力上升300。'),
(73216412, 'Worm Drake', '鳞虫', 'ワームドレイク', 'Normal Monster', 'Reptile', 'EARTH', 4, 1400, 1500, '被那修长的身体卷住后插翅难逃。'),
(14936691, 'Worm Erokin', '伊洛金异虫', 'ワーム・イーロキン', 'Effect Monster', 'Reptile', 'LIGHT', 6, 2400, 1200, '这张卡不能特殊召唤。选择场上表侧表示存在的1只名字带有「异虫」的爬虫类族怪兽变成里侧守备表示。这个效果1回合只能使用1次。'),
(58760121, 'Worm Falco', '法尔科异虫', 'ワーム・ファルコ', 'Flip Effect Monster', 'Reptile', 'LIGHT', 2, 500, 800, '反转：自己场上表侧表示存在的这张卡以外的名字带有「异虫」的爬虫类族怪兽全部变成里侧守备表示。'),
(85754829, 'Worm Gulse', '格鲁斯异虫', 'ワーム・グルス', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1500, 300, '每次场上里侧守备表示存在的怪兽反转，给这张卡放置1个虫指示物。这张卡放置的虫指示物每有1个，这张卡的攻击力上升300。'),
(11159464, 'Worm Hope', '霍普异虫', 'ワーム・ホープ', 'Flip Effect Monster', 'Reptile', 'LIGHT', 1, 800, 1500, '反转：被对方怪兽的攻击反转的场合，从自己卡组抽1张卡。此外，这张卡从场上送去墓地时，自己把1张手卡送去墓地。'),
(57543573, 'Worm Illidan', '伊利丹异虫', 'ワーム・イリダン', 'Effect Monster', 'Reptile', 'LIGHT', 5, 2000, 1800, '每次自己场上有卡被盖放，给这张卡放置1个虫指示物。可以通过把这张卡放置的2个虫指示物取除，选择对方场上1张卡破坏。'),
(84932271, 'Worm Jetelikpse', '贾特里克普斯异虫', 'ワーム・ジェートリクプス', 'Flip Effect Monster', 'Reptile', 'LIGHT', 3, 1200, NULL, '反转：这个回合这张卡被破坏送去墓地时，这张卡在自己场上守备表示特殊召唤。'),
(10026986, 'Worm King', '异虫王', 'ワーム・キング', 'Effect Monster', 'Reptile', 'LIGHT', 8, 2700, 1100, '这张卡可以用1只名字带有「异虫」的爬虫类族怪兽解放表侧攻击表示上级召唤。可以把自己场上存在的1只名字带有「异虫」的爬虫类族怪兽解放，对方场上1张卡破坏。'),
(44811425, 'Worm Linx', '林克斯异虫', 'ワーム・リンクス', 'Flip Effect Monster', 'Reptile', 'LIGHT', 2, 300, 1000, '反转：这张卡在结束阶段时表侧表示存在的场合，自己从卡组抽1张卡。'),
(71315423, 'Worm Millidith', '米利迪斯异虫', 'ワーム・ミリディス', 'Flip Effect Monster', 'Reptile', 'LIGHT', 4, 400, 1600, '反转：这张卡可以当作装备卡使用给1只对方怪兽装备。每次准备阶段，给与装备怪兽的控制者400分伤害。'),
(7700132, 'Worm Noble', '异虫贵族', 'ワーム・ノーブル', 'Flip Effect Monster', 'Reptile', 'LIGHT', 6, 1500, 2400, '反转：被对方怪兽的攻击反转的场合，给与对方基本分向这张卡攻击的对方怪兽的攻击力一半数值的伤害。'),
(28465301, 'Worm Opera', '欧佩拉异虫', 'ワーム・オペラ', 'Flip Effect Monster', 'Reptile', 'LIGHT', 2, 400, 800, '反转：名字带有「异虫」的爬虫类族怪兽以外的场上表侧表示存在的全部怪兽的攻击力下降500。'),
(54860010, 'Worm Prince', '异虫王子', 'ワーム・プリンス', 'Effect Monster', 'Reptile', 'LIGHT', 6, 2200, 400, '这张卡战斗破坏对方怪兽的场合，可以从自己卡组把1只名字带有「异虫」的爬虫类族怪兽加入手卡。自己场上没有这张卡以外的名字带有「异虫」的爬虫类族怪兽存在的场合，结束阶段时这张卡破坏。'),
(81254059, 'Worm Queen', '异虫女王', 'ワーム・クィーン', 'Effect Monster', 'Reptile', 'LIGHT', 8, 2700, 1100, '这张卡可以把1只名字带有「异虫」的爬虫类族怪兽解放表侧攻击表示上级召唤。1回合1次，可以把自己场上存在的1只名字带有「异虫」的爬虫类族怪兽解放，解放怪兽的等级以下的1只名字带有「异虫」的爬虫类族怪兽从自己卡组特殊召唤。'),
(17649753, 'Worm Rakuyeh', '勒库耶异虫', 'ワーム・ルクイエ', 'Effect Monster', 'Reptile', 'LIGHT', 4, 2100, 1200, '这张卡若不在这张卡反转的回合则不能攻击宣言。这张卡攻击的场合，战斗阶段结束时变成里侧守备表示。'),
(3204467, 'Worm Solid', '索利德异虫', 'ワーム・ソリッド', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1000, 1600, '这张卡的守备力上升自己墓地存在的名字带有「异虫」的爬虫类族怪兽数量×100的数值。这张卡被攻击，对方玩家受到战斗伤害的场合，那个伤害步骤结束时把对方场上存在的1张魔法或者陷阱卡破坏。'),
(30299166, 'Worm Tentacles', '腾塔克尔斯异虫', 'ワーム・テンタクルス', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1700, 700, '把自己墓地存在的1只名字带有「异虫」的爬虫类族怪兽从游戏中除外发动。这个回合这张卡在同1次的战斗阶段中可以作2次攻击。这个效果1回合只能使用1次。'),
(43140792, 'Worm Token', '异虫饵', 'ワーム・ベイト', 'Token', 'Insect', NULL, NULL, NULL, NULL, NULL),
(76683171, 'Worm Ugly', '阿格里异虫', 'ワーム・アグリィ', 'Effect Monster', 'Reptile', 'LIGHT', 1, 100, 100, '把这张卡解放对名字带有「异虫」的爬虫类族怪兽的上级召唤成功时，自己墓地存在的这张卡可以在对方场上表侧攻击表示特殊召唤。'),
(2088870, 'Worm Victory', '维多利异虫', 'ワーム・ヴィクトリー', 'Flip Effect Monster', 'Reptile', 'LIGHT', 7, NULL, 2500, '反转：名字带有「异虫」的爬虫类族怪兽以外的场上表侧表示存在的怪兽全部破坏。这张卡的攻击力上升自己墓地存在的名字带有「异虫」的爬虫类族怪兽数量×500的数值。'),
(35638627, 'Worm Warlord', '异虫战神', 'ワーム・ウォーロード', 'Effect Monster', 'Reptile', 'LIGHT', 6, 2350, 1800, '这张卡不能特殊召唤。这张卡战斗破坏的效果怪兽的效果无效化。这张卡战斗破坏对方怪兽的场合，只有1次可以继续攻击。'),
(11722335, 'Worm Xex', '泽克斯异虫', 'ワーム・ゼクス', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1800, 1000, '这张卡召唤成功时，可以从自己卡组把1只名字带有「异虫」的爬虫类族怪兽送去墓地。自己场上有「亚冈异虫」表侧表示存在的场合，这张卡不会被战斗破坏。'),
(47111934, 'Worm Yagan', '亚冈异虫', 'ワーム・ヤガン', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1000, 1800, '自己场上存在的怪兽只有「泽克斯异虫」1只的场合，自己墓地存在的这张卡可以在自己场上里侧守备表示盖放。这个效果特殊召唤的这张卡从场上离开的场合从游戏中除外。这张卡反转时，对方场上表侧表示存在的1只怪兽回到持有者手卡。'),
(74506079, 'Worm Zero', '异虫·零', 'ワーム・ゼロ', 'Fusion Monster', 'Reptile', 'LIGHT', 10, -1, NULL, '名字带有「异虫」的爬虫类族怪兽×2只以上 这张卡的攻击力变成作为融合素材的怪兽种类×500的数值。这张卡得到作为融合素材的怪兽种类的以下效果。 ●2种类以上：1回合1次，可以把自己墓地1只爬虫类族怪兽里侧守备表示特殊召唤。 ●4种类以上：可以把自己墓地1只爬虫类族怪兽从游戏中除外，场上1只怪兽送去墓地。 ●6种类以上：1回合1次，从自己卡组抽1张卡。'),
(69750536, 'Wow Warrior', '鱼战士', '魚ギョ戦士', 'Normal Monster', 'Fish', 'WATER', 4, 1250, 900, '拥有手和脚的鱼人兽，用尖锐的牙齿撕咬敌人。'),
(52098461, 'Wrath of Neos', '新宇侠之怒', 'ラス・オブ・ネオス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己的怪兽区域1只「元素英雄 新宇侠」为对象才能发动。那只「元素英雄 新宇侠」回到持有者卡组，场上的卡全部破坏。'),
(28139785, 'Wrecker Panda', '拖吊小熊猫', 'レッカーパンダ', 'Effect Monster', 'Beast', 'EARTH', 2, 800, 800, '①：自己·对方的准备阶段支付500基本分才能发动。自己卡组最上面的卡送去墓地，那张卡是怪兽的场合，这张卡的攻击力·守备力上升那只怪兽的等级×200。 ②：这张卡被对方破坏送去墓地的场合才能发动。从自己墓地把1只等级最低的怪兽加入手卡。'),
(17238333, 'Wretched Ghost of the Attic', '阁楼中的怪物', '屋根裏の物の怪', 'Normal Monster', 'Fiend', 'DARK', 2, 550, 400, '各家屋顶都有的冤魂。从不做坏事。'),
(6480253, 'Wroughtweiler', '支援犬', 'フレンドッグ', 'Effect Monster', 'Machine', 'EARTH', 3, 800, 1200, '这张卡被战斗破坏送去墓地时，从自己墓地选择1张名字带有「元素英雄」的卡以及1张「融合」加入手卡。'),
(58996430, 'Wulf, Lightsworn Beast', '光道野兽 沃尔夫', 'ライトロード・ビースト ウォルフ', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 2100, 300, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：这张卡从卡组送去墓地的场合发动。这张卡特殊召唤。'),
(86395581, 'Wynn the Wind Channeler', '风灵媒师 薇茵', '風霊媒師ウィン', 'Effect Monster', 'Spellcaster', 'WIND', 5, 1850, 1500, '这个卡名在规则上也当作「灵使」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1只风属性怪兽丢弃才能发动。除「风灵媒师 薇茵」外的1只守备力1500以下的风属性怪兽从卡组加入手卡。这个效果的发动后，直到回合结束时自己不能把风属性以外的怪兽的效果发动。 ②：自己的风属性怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。'),
(37744402, 'Wynn the Wind Charmer', '风灵使 薇茵', '風霊使いウィン', 'Flip Effect Monster', 'Spellcaster', 'WIND', 3, 500, 1500, '①：这张卡反转的场合，以对方场上1只风属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到作为对象的怪兽的控制权。'),
(30674956, 'Wynn the Wind Charmer, Verdant', '苍翠之风灵使 薇茵', '蒼翠の風霊使いウィン', 'Link Monster', 'Spellcaster', 'WIND', NULL, 1850, NULL, '包含风属性怪兽的怪兽2只 这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：以对方墓地1只风属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的风属性怪兽加入手卡。'),
(70860415, 'X-Cross Cannon', 'X－交叉加农', 'X－クロス・キャノン', 'Effect Monster', 'Machine', 'LIGHT', 4, 1800, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：机械族·光属性的，融合怪兽或同盟怪兽在自己场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。可以给这张卡装备的1只机械族·光属性同盟怪兽当作那个效果的装备魔法卡使用从卡组给这张卡装备。这个回合，自己不是光属性怪兽不能从额外卡组特殊召唤。'),
(62651957, 'X-Head Cannon', 'X－首领加农', 'X－ヘッド・キャノン', 'Normal Monster', 'Machine', 'LIGHT', 4, 1800, 1500, '装备强力加农炮，具备合体能力的怪兽。驱使合体和分离施展各种攻击。'),
(66393507, 'X-Krawler Neurogos', '超机怪虫・神经元逻各斯', 'エクスクローラー・ニューロゴス', 'Link Monster', 'Insect', 'EARTH', NULL, 1900, NULL, '昆虫族怪兽2只 ①：这张卡所连接区的「机怪虫」怪兽不会被战斗破坏，攻击力·守备力上升300，和对方怪兽进行战斗的场合，给与对方的战斗伤害变成2倍。 ②：表侧表示的这张卡因对方的效果从场上离开的场合或者被战斗破坏的场合，以自己墓地2只「机怪虫」怪兽为对象才能发动（同名卡最多1张）。那些怪兽里侧守备表示特殊召唤。'),
(92781606, 'X-Krawler Qualiark', '超机怪虫・感质方舟', 'エクスクローラー・クオリアーク', 'Link Monster', 'Insect', 'EARTH', NULL, 2000, NULL, '「机怪虫」怪兽2只 ①：自己场上的「机怪虫」怪兽数量对应的以下适用。 ●2只以上：自己场上的怪兽的攻击力·守备力上升300。 ●4只以上：对方在战斗阶段中不能把效果发动。 ●6只以上：自己怪兽可以直接攻击。 ②：表侧表示的这张卡因对方的效果从场上离开的场合或者被战斗破坏的场合，以自己墓地2只「机怪虫」怪兽为对象才能发动（同名卡最多1张）。那些怪兽里侧守备表示特殊召唤。'),
(39998992, 'X-Krawler Synaphysis', '超机怪虫・突触本性', 'エクスクローラー・シナプシス', 'Link Monster', 'Insect', 'EARTH', NULL, 1800, NULL, '地属性怪兽2只 ①：这张卡所连接区的「机怪虫」怪兽不会被战斗破坏，攻击力·守备力上升300，同1次的战斗阶段中最多2次可以向怪兽攻击。 ②：表侧表示的这张卡因对方的效果从场上离开的场合或者被战斗破坏的场合，以自己墓地2只「机怪虫」怪兽为对象才能发动（同名卡最多1张）。那些怪兽里侧守备表示特殊召唤。'),
(90508760, 'X-Saber Airbellum', 'X－军刀 艾亚贝伦', 'X－セイバー エアベルン', 'Tuner Monster', 'Beast', 'EARTH', 3, 1600, 200, '①：这张卡直接攻击给与对方战斗伤害的场合发动。对方手卡随机选1张丢弃。'),
(23115241, 'X-Saber Anu Piranha', 'X－军刀 安娜佩雷拉', 'X－セイバー アナペレラ', 'Normal Monster', 'Warrior', 'EARTH', 4, 1800, 1100, '以华丽的攻击和冷静的判断飞舞于战场的X-剑士之女战士。她那时而冷酷的攻击令敌人畏惧。'),
(53100061, 'X-Saber Axel', 'X-剑士 阿克塞尔', 'X－セイバー アクセル', 'Effect Monster', 'Beast-Warrior', 'EARTH', 1, 400, 100, '只要这张卡在自己场上表侧表示存在，名字带有「剑士」的怪兽被战斗破坏送去墓地时，从自己卡组抽1张卡。'),
(45462306, 'X-Saber Bruno', 'X－军刀 布鲁诺', 'X－セイバー ブルノ', 'Tuner Monster', 'Psychic', 'EARTH', 3, 1200, 1100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从自己的手卡·场上（表侧表示）·墓地把这张卡以外的1只地属性怪兽除外才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把1张「剑士」魔法·陷阱卡加入手卡。 ③：1回合1次，对方的主要阶段以及战斗阶段才能发动。只用包含这张卡的自己场上的地属性怪兽为素材进行同调召唤。'),
(50604950, 'X-Saber Galahad', 'X-剑士 加拉哈德', 'X－セイバー ガラハド', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 800, '这张卡向对方怪兽攻击的场合，伤害步骤内攻击力上升300。这张卡被对方怪兽攻击的场合，伤害步骤内攻击力下降500。这张卡被选择作为攻击对象时，可以把自己场上存在的这张卡以外的1只名字带有「剑士」的怪兽解放，那次攻击无效。'),
(8252010, 'X-Saber Gottoms', 'X－军刀 加特姆士', 'X－セイバー ガトムズ', 'Synchro Monster', 'Warrior', 'EARTH', 7, 2600, 2100, '调整＋地属性怪兽1只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组把1张「剑士」魔法·陷阱卡或「加特姆士」魔法·陷阱卡加入手卡。 ②：这张卡给与对方战斗伤害时才能发动。对方手卡随机1张丢弃。 ③：这张卡在墓地存在的状态，自己的「X-剑士」怪兽被选择作为攻击对象时才能发动。这张卡特殊召唤。那之后，攻击对象转移为这张卡。'),
(96099959, 'X-Saber Palomuro', 'X-剑士 巴勒姆罗', 'X－セイバー パロムロ', 'Tuner Monster', 'Reptile', 'EARTH', 1, 200, 300, '自己场上存在的名字带有「剑士」的怪兽被战斗破坏送去墓地时，可以支付500基本分，这张卡从墓地特殊召唤。'),
(23093604, 'X-Saber Pashuul', 'X－军刀 帕修尔', 'X－セイバー パシウル', 'Tuner Monster', 'Warrior', 'EARTH', 2, 100, NULL, '①：这张卡不会被战斗破坏。 ②：对方准备阶段发动。自己受到1000伤害。这个效果在这张卡在怪兽区域表侧守备表示存在的场合进行发动和处理。'),
(9978697, 'X-Saber Perina', 'X－军刀 佩利那', 'X－セイバー ペリナ', 'Tuner Monster', 'Beast-Warrior', 'EARTH', 4, 1700, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，把这张卡送去墓地才能发动。从卡组把「X-剑士 佩里娜」以外的2只「X-剑士」怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。 ②：这张卡作为「X-剑士」同调怪兽的同调素材送去墓地的场合才能发动。从以下选1个适用。 ●那只怪兽在同1次的战斗阶段中可以作2次攻击。 ●那只怪兽可以直接攻击。'),
(63612442, 'X-Saber Souza', 'X－军刀 索扎', 'X－セイバー ソウザ', 'Synchro Monster', 'Warrior', 'EARTH', 7, 2500, 1600, '调整＋调整以外的「X-剑士」怪兽1只以上 ①：把自己场上1只「X-剑士」怪兽解放，从以下效果选择1个才能发动。那个效果直到回合结束时得到。 ●这张卡和怪兽进行战斗的伤害步骤开始时发动。那只怪兽破坏。 ●这张卡不会被陷阱卡的效果破坏。'),
(80108118, 'X-Saber Urbellum', 'X－军刀 乌尔贝尔姆', 'X－セイバー ウルベルム', 'Synchro Monster', 'Warrior', 'EARTH', 7, 2200, 1300, '调整＋调整以外的怪兽1只以上 对方手卡有4张以上的场合，这张卡给与对方基本分战斗伤害时，对方手卡随机1张回到卡组最上面。'),
(26993374, 'X-Saber Uruz', 'X-剑士 乌尔德', 'X－セイバー ウルズ', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1600, 1000, '这张卡战斗破坏对方怪兽送去墓地时，可以把这张卡解放，破坏的卡回到持有者卡组最上面。'),
(83810690, 'X-Saber Wayne', 'X－军刀 韦恩', 'X－セイバー ウェイン', 'Synchro Monster', 'Warrior', 'EARTH', 5, 2100, 400, '调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功时才能发动。从手卡把1只4星以下的战士族怪兽特殊召唤。'),
(5852388, 'Xeno Meteorus', '异界厄兆陨龙', 'ゼノ・メテオロス', 'Tuner Monster', 'Dinosaur', 'FIRE', 6, 2000, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：卡被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。选自己的手卡·场上1只恐龙族怪兽破坏。那之后，从手卡·卡组把1只恐龙族通常怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是龙族·恐龙族·海龙族·幻龙族怪兽不能从额外卡组特殊召唤。'),
(71692913, 'Xiangke Magician', '相克的魔术师', '相克の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 7, 2500, 500, '①：1回合1次，以场上1只光属性怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(17086528, 'Xiangsheng Magician', '相生的魔术师', '相生の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 4, 500, 1500, '①：这张卡的战斗发生的对对方的战斗伤害变成0。 ②：1回合1次，以这张卡以外的自己场上1只怪兽为对象才能发动。这张卡的攻击力直到回合结束时变成和那只怪兽相同。'),
(76515293, 'Xing Zhen Hu', '心镇壶', '心鎮壷', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择场上盖放的2张魔法·陷阱卡才能发动。只要这张卡在场上存在，选择的魔法·陷阱卡不能发动。'),
(40736921, 'Xing Zhen Hu Replica', '心镇壶的复制品', '心鎮壷のレプリカ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择场上盖放的1张魔法·陷阱卡发动。只要这张卡在场上存在，选择的卡不能发动。不能对应这张卡的发动把魔法·陷阱·效果怪兽的效果发动。'),
(58004362, 'Xtra HERO Cross Crusader', '特异－英雄 十字魔侠', 'X・HERO クロスガイ', 'Link Monster', 'Warrior', 'DARK', NULL, 1600, NULL, '战士族怪兽2只 这个卡名的①②的效果1回合各能使用1次，这张卡的效果发动的回合，自己不是「英雄」怪兽不能特殊召唤。 ①：这张卡连接召唤的场合，以自己墓地1只「命运英雄」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把自己场上1只「命运英雄」怪兽解放才能发动。和解放的怪兽卡名不同的1只「英雄」怪兽从卡组加入手卡。'),
(63813056, 'Xtra HERO Dread Decimator', '特异－英雄 恐惧破坏者', 'X・HERO ドレッドバスター', 'Link Monster', 'Warrior', 'DARK', NULL, 2500, NULL, '「英雄」怪兽2只以上 ①：这张卡以及这张卡所连接区的「英雄」怪兽的攻击力上升自己墓地的「英雄」怪兽种类×100。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(19324993, 'Xtra HERO Infernal Devicer', '特异－英雄 地狱操控者', 'X・HERO ヘル・デバイサー', 'Link Monster', 'Fiend', 'DARK', NULL, 1700, NULL, '「英雄」怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动（这个效果发动的回合，自己不是「英雄」怪兽不能特殊召唤）。额外卡组1只「英雄」融合怪兽给对方观看，那只怪兽有卡名记述的最多2只融合素材怪兽从卡组加入手卡（同名卡最多1张）。 ②：这张卡所连接区的恶魔族怪兽的攻击力·守备力上升自身的等级×100。'),
(1948619, 'Xtra HERO Wonder Driver', '特异－英雄 神奇驱动者', 'X・HERO ワンダー・ドライバー', 'Link Monster', 'Warrior', 'LIGHT', NULL, 1900, NULL, '「英雄」怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：作为这张卡所连接区的自己场上有「英雄」怪兽召唤·特殊召唤的场合，以自己墓地的「融合」魔法卡、「变化」速攻魔法卡的其中1张为对象发动。那张卡在自己场上盖放。 ②：这张卡被战斗或者对方的效果破坏送去墓地的场合才能发动。从手卡把1只「英雄」怪兽特殊召唤。'),
(31213049, 'XX-clusion', 'XX排除', 'XXクルージョン', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方把手卡的怪兽的效果发动时才能发动。那个发动无效。有对方手卡的场合，再让对方选1张手卡丢弃。'),
(5998840, 'XX-Saber Boggart Knight', 'XX－军刀 波加骑士', 'XX－セイバー ボガーナイト', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1900, 1000, '把这张卡作为同调素材的场合，不是「X-剑士」怪兽的同调召唤不能使用。 ①：这张卡召唤时才能发动。从手卡把1只4星以下的「X-剑士」怪兽特殊召唤。'),
(31383545, 'XX-Saber Darksoul', 'XX－军刀 暗魂', 'XX－セイバー ダークソウル', 'Effect Monster', 'Beast', 'EARTH', 3, 100, 100, '①：这张卡从自己场上送去墓地的回合的结束阶段才能发动。从卡组把1只「X-剑士」怪兽加入手卡。'),
(42737833, 'XX-Saber Emmersblade', 'XX－军刀 埃摩斯剑刃', 'XX－セイバー エマーズブレイド', 'Effect Monster', 'Insect', 'EARTH', 3, 1300, 800, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只4星以下的「X-剑士」怪兽特殊召唤。'),
(51808422, 'XX-Saber Faultroll', 'XX－军刀 佛洛托尔', 'XX－セイバー フォルトロール', 'Effect Monster', 'Warrior', 'EARTH', 6, 2400, 1800, '这张卡不能通常召唤。自己场上有「X-剑士」怪兽2只以上存在的场合才能特殊召唤。 ①：1回合1次，以自己墓地1只4星以下的「X-剑士」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(78422252, 'XX-Saber Fulhelmknight', 'XX－军刀 佛兰姆骑士', 'XX－セイバー フラムナイト', 'Tuner Monster', 'Warrior', 'EARTH', 3, 1300, 1000, '①：只在这张卡在场上表侧表示存在才有1次，对方怪兽的攻击宣言时以那1只怪兽为对象才能发动。那次攻击无效。 ②：这张卡战斗破坏对方的守备表示怪兽的场合，以自己墓地1只4星以下的「X-剑士」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(42024143, 'XX-Saber Gardestrike', 'XX－军刀 突击守卫', 'XX－セイバー ガルドストライク', 'Effect Monster', 'Beast-Warrior', 'EARTH', 5, 2100, 1400, '自己墓地有名字带有「X-剑士」的怪兽2只以上存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(77330185, 'XX-Saber Garsem', 'XX-剑士 加尔塞姆', 'XX－セイバー ガルセム', 'Effect Monster', 'Beast', 'EARTH', 4, 1400, 400, '场上存在的这张卡被卡的效果破坏送去墓地时，从自己卡组把1只名字带有「X-剑士」的怪兽加入手卡。这张卡的攻击力上升自己场上表侧表示存在的名字带有「X-剑士」的怪兽数量×200的数值。'),
(52352005, 'XX-Saber Gottoms', 'XX－军刀 加特姆士', 'XX－セイバー ガトムズ', 'Synchro Monster', 'Beast-Warrior', 'EARTH', 9, 3100, 2600, '调整＋地属性怪兽1只以上 ①：把自己场上1只「X-剑士」怪兽解放才能发动。对方手卡随机1张丢弃。'),
(2203790, 'XX-Saber Hyunlei', 'XX－军刀 迅雷', 'XX－セイバー ヒュンレイ', 'Synchro Monster', 'Warrior', 'EARTH', 6, 2300, 1300, '调整＋调整以外的「X-剑士」怪兽1只以上 ①：这张卡同调召唤时，以场上最多3张魔法·陷阱卡为对象才能发动。那些卡破坏。'),
(87292536, 'XX-Saber Ragigura', 'XX－军刀 雷金古拉', 'XX－セイバー レイジグラ', 'Effect Monster', 'Beast-Warrior', 'EARTH', 1, 200, 1000, '①：这张卡召唤·特殊召唤时，以自己墓地1只「X-剑士」怪兽为对象才能发动。那只怪兽加入手卡。'),
(2111707, 'XY-Dragon Cannon', 'XY－龙型加农炮', 'XY－ドラゴン・キャノン', 'Fusion Monster', 'Machine', 'LIGHT', 6, 2200, 1900, '「X-首领加农」＋「Y-龙头」 把自己场上的上记卡除外的场合才能从额外卡组特殊召唤。这张卡不能作从墓地的特殊召唤。 ①：丢弃1张手卡，以对方场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张对方的表侧表示的卡破坏。'),
(72502414, 'Xyz Agent', '超量谍报士', 'エクシーズ・エージェント', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 900, 300, '这张卡在墓地存在的场合，自己的主要阶段时选择自己场上1只名字带有「希望皇 霍普」的超量怪兽才能发动。把墓地的这张卡在选择的怪兽下面重叠作为超量素材。「超量谍报士」的效果在决斗中只能使用1次。'),
(60623203, 'Xyz Align', '超量排列', 'エクシーズ・アライン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：宣言1～12的任意等级，以包含自己场上的怪兽的场上2只表侧表示怪兽为对象才能发动。那些怪兽的等级直到回合结束时变成宣言的等级。这张卡的发动后，直到回合结束时自己不是和作为对象的怪兽的其中任意种相同种族的怪兽不能从额外卡组特殊召唤。'),
(20145685, 'Xyz Armor Fortress', '超量装甲・要塞', 'エクシーズ・アーマー・フォートレス', 'XYZ Monster', 'Machine', 'WATER', 5, 2500, 1800, '5星怪兽×2 「超量铠甲·要塞式」1回合1次也能在自己场上的3·4阶的超量怪兽上面重叠来超量召唤。持有超量素材的这张卡不能作为超量召唤的素材。 ①：1回合1次，把这张卡最多2个超量素材取除才能发动。把取除数量的「铠装超量」卡从卡组加入手卡（同名卡最多1张）。 ②：有这张卡装备的怪兽用和怪兽的战斗给与对方的战斗伤害变成2倍。'),
(94151981, 'Xyz Armor Torpedo', '超量装甲・鱼雷', 'エクシーズ・アーマー・トルピード', 'XYZ Monster', 'Warrior', 'WATER', 3, 2500, 800, '3星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：没有超量素材的这张卡不能攻击。 ②：把这张卡2个超量素材取除才能发动。自己抽1张。 ③：只要这张卡装备中，以下效果适用。 ●装备怪兽进行战斗的场合，直到伤害步骤结束时，对方不能把卡的效果发动，对方场上的表侧表示怪兽的效果无效化。 ●装备怪兽是超量怪兽的场合，对方不能把装备怪兽作为效果的对象。'),
(86062400, 'Xyz Avenger', '超量复仇者', 'エクシーズ・アヴェンジャー', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, 700, '这张卡不受超量怪兽的效果影响。此外，这张卡被和超量怪兽的战斗破坏送去墓地时，把让这张卡破坏的超量怪兽的阶级的以下效果发动。 ●3阶以下：对方选额外卡组1张卡送去墓地。 ●4阶：自己选对方的额外卡组1张卡送去墓地。 ●5阶以上：对方选那只超量怪兽的阶级数量的额外卡组的卡送去墓地。'),
(19272658, 'Xyz Bento', '超量便当', 'エクシーズ弁当', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上的怪兽被战斗破坏的场合或者被送去墓地的场合，以自己场上1只超量怪兽为对象才能发动。从对方墓地选1只怪兽在作为对象的怪兽下面重叠作为超量素材。 ②：把墓地的这张卡除外，以从额外卡组特殊召唤的场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(44487250, 'Xyz Block', '超量阻挡', 'エクシーズ・ブロック', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方把怪兽的效果发动时，把自己场上1个超量素材取除才能发动。那个发动无效并破坏。'),
(30600344, 'Xyz Burst', '超量爆发', 'エクシーズ・バースト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有6阶以上的超量怪兽存在的场合才能发动。对方场上盖放的卡全部破坏。'),
(11705261, 'Xyz Change Tactics', '超量转换战术', 'エクシーズ・チェンジ・タクティクス', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「超量变身战术」在自己场上只能有1张表侧表示存在。 ②：自己场上有「希望皇 霍普」怪兽超量召唤时，支付500基本分才能发动。自己抽1张。'),
(95471006, 'XYZ Combine', 'X・Y・Z 合体', 'X・Y・Zコンバイン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的机械族·光属性的同盟怪兽卡被除外的场合才能发动。从卡组把「X-首领加农」「Y-龙头」「Z-金属履带」之内1只特殊召唤。 ②：让自己场上1只融合怪兽回到额外卡组才能发动。从除外的自己怪兽之中选「X-首领加农」「Y-龙头」「Z-金属履带」最多2只特殊召唤（同名卡最多1张）。'),
(71541986, 'Xyz Dimension Splash', '超量次元飞溅', 'エクシーズ・ディメンション・スプラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '盖放的这张卡从游戏中除外的场合，可以从卡组把2只水属性·8星怪兽特殊召唤。这个效果特殊召唤的怪兽不能攻击宣言，效果无效化，也不能解放。'),
(57836546, 'Xyz Double Back', '超量双璧同归', 'エクシーズ・ダブル・バック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上的超量怪兽被破坏的回合，自己场上没有怪兽存在的场合才能发动。从自己墓地选择1只那个回合被破坏的超量怪兽和1只那只怪兽的攻击力以下的怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段时破坏。'),
(58628539, 'Xyz Effect', '超量效应', 'エクシーズエフェクト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己超量召唤成功时，选择场上存在的1张卡才能发动。选择的卡破坏。'),
(78610936, 'Xyz Encore', '超量叠光延迟', 'エクシーズ・オーバーディレイ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '不能对应这张卡的发动让魔法·陷阱·怪兽的效果发动。 ①：以持有超量素材的对方场上1只超量怪兽为对象才能发动。那只怪兽的超量素材全部取除，作为对象的怪兽回到额外卡组。取除的超量素材之中有怪兽卡的场合，再把那些怪兽从墓地尽可能往对方场上守备表示特殊召唤。这个效果特殊召唤的怪兽的等级下降1星。'),
(85839825, 'Xyz Energy', '超量能量', 'エクシーズエナジー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1个超量素材取除发动。选择对方场上表侧表示存在的1只怪兽破坏。'),
(81978611, 'Xyz Entrust', '超量托付', 'エクシーズ・エントラスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的卡组·墓地把1张「铠装超量」卡加入手卡。那之后，可以选自己场上最多2只表侧表示怪兽那些等级直到回合结束时全部变成3星或者全部变成5星。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己的魔法与陷阱区域1张当作装备卡使用的超量怪兽卡为对象才能发动。那张卡特殊召唤。'),
(31398842, 'Xyz Force', '超量之力', 'エクシーズ・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把「超量之力」以外的1张「超量」卡送去墓地。有超量怪兽在作为超量素材中的超量怪兽在场上存在的场合，也能不送去墓地加入手卡。 ②：把这个回合没有送去墓地的这张卡从墓地除外才能发动。场上1个超量素材取除。取除的超量素材是超量怪兽的场合，可以再把自己的墓地·除外状态的那只超量怪兽守备表示特殊召唤。'),
(72355441, 'Xyz Gift', '超量礼物', 'エクシーズ・ギフト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有超量怪兽2只以上存在的场合才能发动。自己场上2个超量素材取除，自己从卡组抽2张。'),
(21723081, 'XYZ Hyper Cannon', 'X・Y・Z 高能加农炮', 'X・Y・Zハイパーキャノン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：「XYZ-神龙炮」或者有那个卡名作为融合素材记述的融合怪兽在自己场上存在的场合，可以把这个效果的发动回合的以下效果发动。 ●自己回合：以除外的1只自己的同盟怪兽为对象才能发动。那只怪兽回到卡组最下面，自己从卡组抽1张。 ●对方回合：把手卡任意数量丢弃，以那个数量的对方场上的卡为对象才能发动。那些卡破坏。'),
(14602126, 'Xyz Import', '超量输入', 'エクシーズ・インポート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只超量怪兽和持有那个攻击力以下的攻击力的对方场上1只怪兽为对象才能发动。那只对方怪兽在那只自己怪兽下面重叠作为超量素材。'),
(43150717, 'Xyz Lay', '超量迭光', NULL, 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力上升场上的超量素材的数量×200。1回合1次，可以根据装备怪兽的种类从以下效果选择1个发动。 ●超量怪兽：自己场上2个超量素材取除；从卡组把1张「超量」魔法·陷阱卡在自己场上盖放。 ●那以外：从手卡把和装备怪兽等级相同的1只怪兽效果无效守备表示特殊召唤。 「超量迭光」在1回合只能发动1张。'),
(32999573, 'Xyz Override', '超量超控', 'エクシーズ・オーバーライド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '场上的超量怪兽把那超量素材取除来让效果发动的场合，可以作为取除的1个超量素材的代替而把1张手卡里侧表示从游戏中除外。这个效果双方1回合只能使用1次。'),
(16938770, 'Xyz Poseidon Splash', '超量波塞冬飞溅', 'エクシーズ・ポセイドン・スプラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：有超量怪兽在作为超量素材中的超量怪兽在自己场上存在的场合，宣言场上的怪兽1个属性才能发动。除有装备魔法卡装备的怪兽外的场上的宣言属性的怪兽全部破坏。 ②：把墓地的这张卡除外，把自己场上1个超量素材取除才能发动。从自己墓地把1只鱼族·海龙族·水族怪兽在自己或对方的场上特殊召唤。'),
(26708437, 'Xyz Reborn', '超量重生', 'エクシーズ・リボーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只超量怪兽为对象才能发动。那只怪兽特殊召唤，把这张卡在下面重叠作为超量素材。'),
(74728028, 'Xyz Reception', '超量应接', 'エクシーズ・レセプション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。和那只怪兽相同等级的1只怪兽从手卡特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成0，效果无效化。'),
(2371506, 'Xyz Reflect', '超量反射', 'エクシーズ・リフレクト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '场上的超量怪兽为对象的效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。那之后，给与对方基本分800分伤害。'),
(43138260, 'Xyz Remora', '超量鮣鱼', 'エクシーズ・リモーラ', 'Effect Monster', 'Fish', 'WATER', 4, 800, 800, '①：这张卡可以把自己场上2个超量素材取除，从手卡特殊召唤。 ②：这张卡的①的方法特殊召唤成功时，以自己墓地2只鱼族·4星怪兽为对象才能发动。那些鱼族怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽不能攻击，效果无效化，也不能作表示形式的变更。把这个效果特殊召唤的怪兽作为超量召唤的素材的场合，不是水属性怪兽的超量召唤不能使用。'),
(10275411, 'Xyz Revenge', '超量复仇', 'エクシーズ・リベンジ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上有持有超量素材的超量怪兽存在的场合，选择自己墓地1只超量怪兽才能发动。选择的怪兽特殊召唤，把对方场上1个超量素材在选择的怪兽下面重叠作为超量素材。「超量复仇」在1回合只能发动1张。'),
(31554054, 'Xyz Revenge Shuffle', '超量复仇切换', 'エクシーズ・リベンジ・シャッフル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的超量怪兽被选择作为攻击对象时，选择自己墓地1只超量怪兽才能发动。成为攻击对象的超量怪兽回到持有者的额外卡组。那之后，选择的怪兽从墓地特殊召唤，把这张卡在下面重叠作为超量素材。'),
(66604523, 'Xyz Reversal', '超量逆转', 'エクシーズ・リバーサル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上1只超量怪兽和自己场上1只超量怪兽才能发动。选择的怪兽的控制权交换。'),
(32764863, 'Xyz Revive Splash', '超量复苏飞溅', 'エクシーズ・リバイブ・スプラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己墓地1只4阶以下的超量怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽变成水属性。 ②：把墓地的这张卡除外，以自己场上1只水属性超量怪兽为对象才能发动。比那只自己怪兽阶级高1阶的1只水属性超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(8339504, 'Xyz Shift', '超量调换', 'エクシーズ・シフト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只超量怪兽解放才能发动。和解放的怪兽相同种族·属性·阶级而卡名不同的1只怪兽从额外卡组特殊召唤，把这张卡在下面重叠作为超量素材。这个效果特殊召唤的怪兽在结束阶段时送去墓地。「超量调换」在1回合只能发动1张。'),
(7850740, 'Xyz Slidolphin', '超量滑水海豚', 'エクシーズ・スライドルフィン', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1200, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有超量怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡在墓地存在，自己场上有超量怪兽特殊召唤的场合，以那1只超量怪兽为对象才能发动。把这张卡在那只怪兽下面重叠作为超量素材。这个效果在这张卡送去墓地的回合不能发动。'),
(11228035, 'Xyz Soul', '超量之魂', 'エクシーズ・ソウル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己或者对方的墓地1只超量怪兽才能发动。自己场上存在的全部怪兽的攻击力直到结束阶段时上升选择的怪兽的阶级×200的数值。那之后，可以让选择的怪兽回到额外卡组。'),
(4545854, 'Xyz Territory', '超量领域', 'エクシーズ・テリトリー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '只在超量怪兽和怪兽进行战斗的伤害计算时，那些超量怪兽的攻击力·守备力上升那个阶级×200的数值。场上的这张卡被卡的效果破坏的场合，可以作为代替把自己场上1个超量素材取除。'),
(32086564, 'Xyz Tribalrivals', '超量同门对手', 'エクシーズ・トライバル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，持有超量素材2个以上的超量怪兽不会被效果破坏。 ②：这张卡在魔法与陷阱区域存在，自己的超量怪兽和对方怪兽进行战斗的伤害计算后发动。那只对方怪兽破坏。这个效果在那只自己怪兽持有超量素材2个以上的场合才能发动和处理。'),
(13032689, 'Xyz Unit', '超量组件', 'エクシーズ・ユニット', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '超量怪兽才能装备。装备怪兽的攻击力上升装备怪兽的阶级×200的数值。此外，自己场上的装备怪兽把超量素材取除来让效果发动的场合，这张卡可以当作取除的超量素材中的1个使用。'),
(11109820, 'Xyz Universe', '超量宇宙', 'エクシーズ・ユニバース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上2只超量怪兽为对象才能发动。那2只怪兽送去墓地。那之后，把持有和那2只超量怪兽的阶级合计相同或低1阶的阶级的1只「No.」怪兽以外的超量怪兽从额外卡组特殊召唤，把这张卡在下面重叠作为超量素材。这张卡的发动后，直到回合结束时对方受到的全部伤害变成0。'),
(96457619, 'Xyz Veil', '超量遮护罩', 'エクシーズ・ヴェール', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，双方玩家不能把场上表侧表示存在的持有超量素材的超量怪兽作为卡的效果的对象。'),
(99064191, 'Xyz Wrath', '超量诛罚', 'エクシーズ・パニッシュ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，自己场上有超量怪兽存在，5星以上的效果怪兽的效果发动时，可以通过丢弃1张手卡，那个效果无效并破坏。'),
(57319935, 'Xyz Xtreme !!', '超量热战！！', 'エクシーズ熱戦！！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的超量怪兽被战斗破坏时，支付1000基本分才能发动。双方玩家从各自的额外卡组选持有破坏的怪兽的阶级以下的阶级的1只超量怪兽给对方观看。把攻击力低的怪兽给人观看的玩家受到对方给人观看的怪兽的攻击力和自己给人观看的怪兽的攻击力的相差数值的伤害。对方没把怪兽给人观看的场合，给与对方基本分自己给人观看的怪兽的攻击力数值的伤害。'),
(91998119, 'XYZ-Dragon Cannon', 'XYZ－龙型加农炮', 'XYZ－ドラゴン・キャノン', 'Fusion Monster', 'Machine', 'LIGHT', 8, 2800, 2600, '「X-首领加农」＋「Y-龙头」＋「Z-金属履带」 把自己场上的上记的卡除外的场合才能从额外卡组特殊召唤。这张卡不能从墓地特殊召唤。 ①：丢弃1张手卡，以对方场上1张卡为对象才能发动。那张对方的卡破坏。'),
(75748977, 'XYZ-Hyper Dragon Cannon', 'XYZ－高能龙型加农炮', 'XYZ－ハイパー・ドラゴン・キャノン', 'Fusion Monster', 'Machine', 'LIGHT', 9, 3000, 2800, '「X-交错加农」＋「Y-机敏龙头」＋「Z-无穷履带」 把自己的场上·墓地的上记的卡除外的场合才能从额外卡组特殊召唤。 ①：对方回合1次，丢弃1张手卡，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：把场上·墓地的这张卡除外，把额外卡组1只机械族·光属性·8星融合怪兽给对方观看才能发动。那只怪兽有卡名记述的自己的墓地·除外状态的最多3只融合素材怪兽特殊召唤。'),
(86559484, 'Xyz-Raypierce', '超量透视细剑龙', 'X－レイ・ピアース', 'Effect Monster', 'Dragon', 'FIRE', 4, 1700, 200, '「超量透视细剑龙」的①②的效果1回合各能使用1次。 ①：从自己墓地把龙族怪兽和幻龙族怪兽各1只除外才能发动。从手卡·卡组把1只「超量透视细剑龙」特殊召唤。 ②：这张卡从场上送去墓地的场合才能发动。给与对方500伤害。'),
(99724761, 'XZ-Tank Cannon', 'XZ－履带加农炮', 'XZ－キャタピラー・キャノン', 'Fusion Monster', 'Machine', 'LIGHT', 6, 2400, 2100, '「X-首领加农」＋「Z-金属履带」 把自己场上的上记卡除外的场合才能从额外卡组特殊召唤。这张卡不能作从墓地的特殊召唤。 ①：丢弃1张手卡，以对方场上1张里侧表示的魔法·陷阱卡为对象才能发动。那张对方的里侧表示的卡破坏。'),
(65622692, 'Y-Dragon Head', 'Y－龙首', 'Y－ドラゴン・ヘッド', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 1500, 1600, '①：1回合1次，可以把1个以下效果发动。 ●以自己场上1只「X-首领加农」为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。 ②：装备怪兽的攻击力·守备力上升400。'),
(6355563, 'Y-Yare Head', 'Y－敏捷龙首', 'Y－ドラゴン・イアヘッド', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 1500, 1600, '①：这张卡特殊召唤的场合才能发动。从自己的手卡·墓地把1只机械族·光属性·4星怪兽当作装备魔法卡使用给这张卡装备。这个回合，自己不是光属性怪兽不能从额外卡组特殊召唤。 ②：1回合1次，可以把1个以下效果发动。 ●以自己场上1只机械族怪兽为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。'),
(29792472, 'Yad''al-Hecahands', '百臂无形招引手', '見えざる招き手', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「不可见之手」怪兽存在，对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。那之后，可以把破坏的魔法·陷阱卡在自己场上盖放。'),
(29380133, 'Yado Karu', '寄居龙', 'ヤドカリュー', 'Effect Monster', 'Aqua', 'WATER', 4, 900, 1700, '这张卡的表示形式从攻击表示变成表侧守备表示时，可以从自己手卡把任意数量的卡回到卡组最下面。'),
(13298352, 'Yaguramaru the Armor Ninja', '胄之忍者-橹丸', '冑の忍者－櫓丸', 'Fusion Monster', 'Machine', 'DARK', 5, 2000, 2000, '种族不同的「忍者」怪兽×2 这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把自己场上的上记卡解放的场合可以从额外卡组特殊召唤。 ①：这张卡特殊召唤·反转的场合，从自己的手卡·墓地以及自己场上的表侧表示的卡之中把这张卡以外的1张「忍者」卡或者「忍法」卡除外，以场上1张卡为对象才能发动。那张卡除外。这个卡名的这个效果1回合只能使用1次。'),
(10315429, 'Yaiba Robo', '切割机器人', 'カッター・ロボ', 'Normal Monster', 'Machine', 'DARK', 4, 1000, 1300, '方形的身体内部隐藏着无数刀刃、能切碎一切的机械。'),
(10852583, 'Yajiro Invader', '弥次郎侵略者', 'ヤジロベーダー', 'Effect Monster', 'Reptile', 'DARK', 5, 2200, NULL, '①：这张卡往中央以外的主要怪兽区域召唤·特殊召唤的场合破坏。 ②：1回合1次，自己主要阶段才能发动。这张卡向相邻的没有使用的主要怪兽区域移动。 ③：每次对方场上只有怪兽1只召唤·特殊召唤发动。那只对方怪兽的位置是和这张卡不同纵列的场合，这张卡向要往那只对方怪兽靠近的相邻的主要怪兽区域移动。那之后，和移动过的这张卡相同纵列的其他卡全部破坏。'),
(94215860, 'Yaksha', '夜叉', '夜叉', 'Spirit Monster', 'Fairy', 'WATER', 4, 1900, 1500, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡召唤·反转时，可以选择对方场上存在的1张魔法·陷阱卡回到持有者手卡。'),
(90583279, 'Yakusa, Lord of the Eight Thunders', '八雷天神', '八雷天神', 'Effect Monster', 'Wyrm', 'LIGHT', 8, 2000, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡可以把自己墓地1只等级或者阶级是8的怪兽除外，从手卡特殊召唤。 ②：以自己墓地1只等级或者阶级是8的仪式·融合·同调·超量怪兽为对象才能发动。那只怪兽回到卡组。那之后，回去的怪兽种类的以下效果适用。 ●仪式·融合：自己从卡组抽1张。 ●同调·超量：这张卡的攻击力上升1000。'),
(70345785, 'Yamadron', '三头巨龙', 'ヤマドラン', 'Normal Monster', 'Dragon', 'FIRE', 5, 1600, 1800, '用三个头不断地喷火，使周围一带变成火海！'),
(76862289, 'Yamata Dragon', '八俣大龙', '八俣大蛇', 'Spirit Monster', 'Dragon', 'FIRE', 7, 2600, 3100, '这张卡不能特殊召唤。 ①：这张卡给与对方战斗伤害的场合发动。自己直到手卡变成5张为止从卡组抽卡。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(4632019, 'Yamatako Orochi', '八岐大章鱼', 'ヤマタコオロチ', 'Tuner Monster', 'Sea Serpent', 'WATER', 1, NULL, 800, '①：把场上的这张卡作为同调素材的场合，可以把这张卡的等级当作8星使用。 ②：这张卡为同调素材的同调怪兽得到那自身原本等级的以下效果。 ●8星以下：这张卡的攻击力·守备力上升800。 ●9星以上：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(76704943, 'Yamatano Dragon Scroll', '八俣龙绘卷', 'ヤマタノ竜絵巻', 'Normal Monster', 'Dragon', 'WIND', 2, 900, 300, '画卷上的龙实体化后进行攻击。守备力很低。'),
(82841979, 'Yamato-no-Kami', '大和神', '大和神', 'Spirit Monster', 'Warrior', 'DARK', 6, 2200, 1200, '这张卡不能通常召唤。把自己墓地存在的1只灵魂怪兽从游戏中除外的场合才能特殊召唤。特殊召唤的回合的结束阶段时回到持有者手卡。这张卡战斗破坏对方怪兽的场合，可以把对方场上存在的1张魔法或者陷阱卡破坏。'),
(59197169, 'Yami', '暗', '闇', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '场上表侧表示存在的恶魔族·魔法师族怪兽的攻击力·守备力上升200。场上表侧表示存在的天使族怪兽的攻击力·守备力下降200。'),
(24181936, 'Yaminabe Party', '暗味锅派对', '闇味鍋パーティー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己战斗阶段开始时，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只自己怪兽的攻击对象由对方选择，那只自己怪兽的攻击力只在和对方怪兽进行战斗的伤害计算时上升自身的原本攻击力数值。'),
(51474037, 'Yamorimori', '家井守宫', 'ヤモイモリ', 'Effect Monster', 'Reptile', 'WATER', 2, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：可以把墓地的这张卡除外，以自己场上1只爬虫类族怪兽和对方场上1只表侧表示怪兽为对象，从以下效果选择1个发动。 ●作为对象的怪兽变成里侧守备表示。 ●作为对象的自己怪兽破坏，作为对象的对方怪兽的攻击力直到回合结束时变成0。'),
(67249508, 'Yang Zing Brutality', '龙星的凶暴化', '竜星の凶暴化', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的「龙星」怪兽和对方怪兽进行战斗的伤害计算时才能发动。那只自己怪兽的攻击力·守备力只在那次伤害计算时变成原本数值的2倍，伤害步骤结束时破坏。'),
(30398342, 'Yang Zing Creation', '龙星的具象化', '竜星の具象化', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己场上的怪兽被战斗·效果破坏的场合才能把这个效果发动。从卡组把1只「龙星」怪兽特殊召唤。 ②：只要这张卡在魔法与陷阱区域存在，自己不能把同调怪兽以外的怪兽从额外卡组特殊召唤。'),
(17183908, 'Yang Zing Path', '龙星的辉迹', '竜星の輝跡', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「龙星的辉迹」在1回合只能发动1张。 ①：以自己墓地3只「龙星」怪兽为对象才能发动。那3只怪兽回到卡组洗切。那之后，自己从卡组抽2张。'),
(43577607, 'Yang Zing Prana', '龙星的气脉', '竜星の気脈', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：得到自己墓地的「龙星」怪兽的属性种类数量的以下效果。 ●2种类以上：自己场上的「龙星」怪兽的攻击力上升500。 ●3种类以上：自己场上的「龙星」怪兽被战斗·效果破坏的场合，可以作为代替把这张卡送去墓地。 ●4种类以上：对方不能把怪兽盖放，对方场上的表侧表示怪兽全部变成攻击表示。 ●5种类以上：把这张卡送去墓地才能发动。场上的卡全部破坏。'),
(77783947, 'Yang Zing Unleashed', '龙星的极致', '竜星の極み', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，可以攻击的对方怪兽必须作出攻击。 ②：自己或者对方的主要阶段以及战斗阶段把魔法与陷阱区域表侧表示存在的这张卡送去墓地才能把这个效果发动。用包含「龙星」怪兽1只以上的怪兽为素材把1只同调怪兽同调召唤。'),
(71280811, 'Yaranzo', '宝箱鬼', 'ヤランゾ', 'Normal Monster', 'Zombie', 'DARK', 4, 1300, 1500, '突袭企图打开宝箱的盗贼。'),
(77714963, 'Yasha, the Skeletal Mayakashi', '骸之魔妖－夜叉', '骸の魔妖－夜叉', 'Effect Monster', 'Zombie', 'DARK', 5, 2000, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡把这张卡以外的1只「魔妖」怪兽丢弃才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，自己不是「魔妖」怪兽不能从额外卡组特殊召唤。'),
(41061625, 'Yashinoki', '椰树', 'ヤシの木', 'Normal Monster', 'Plant', 'EARTH', 2, 800, 600, '有意志的椰子树。以落下的果实进行攻击。果实中的椰汁味道鲜美。'),
(3078576, 'Yata-Garasu', '八汰乌', '八汰烏', 'Spirit Monster', 'Fiend', 'WIND', 2, 200, 100, '这张卡不能特殊召唤。 ①：这张卡给与对方战斗伤害的场合发动。下次的对方抽卡阶段跳过。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到手卡。'),
(43202238, 'Yazi, Evil of the Yang Zing', '邪龙星－睚眦', '邪竜星－ガイザー', 'Synchro Monster', 'Wyrm', 'DARK', 7, 2600, 2100, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：场上的这张卡不会成为对方的效果的对象。 ②：以自己场上1只「龙星」怪兽和对方场上1张卡为对象才能发动。那些卡破坏。 ③：自己场上的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把1只幻龙族怪兽守备表示特殊召唤。'),
(65303664, 'Yellow Baboon, Archer of the Forest', '森之狩人 黄狒狒', '森の狩人イエロー・バブーン', 'Effect Monster', 'Beast', 'EARTH', 7, 2600, 1800, '自己场上存在的兽族怪兽被战斗破坏并送去墓地时，可以把自己墓地存在的2只兽族怪兽从游戏中除外。这张卡从手卡特殊召唤。'),
(90247311, 'Yellow Dragon Ninja', '黄龙忍者', '黄竜の忍者', 'Effect Monster', 'Dinosaur', 'WIND', 8, 3000, 1500, '这张卡不用「忍者」怪兽或者「忍法」卡的效果不能特殊召唤。 ①：1回合1次，从手卡以及自己场上的表侧表示的卡之中把1只「忍者」怪兽和1张「忍法」卡送去墓地，以场上最多2张魔法·陷阱卡为对象才能发动。那些卡破坏。这个效果在对方回合也能发动。'),
(16366810, 'Yellow Duston', '黄尘妖', 'イエロー・ダストン', 'Effect Monster', 'Fiend', 'EARTH', 1, NULL, 1000, '这张卡不能解放，也不能作为融合·同调·超量召唤的素材。场上的这张卡被破坏时，这张卡的控制者选择自己墓地1只怪兽回到卡组。「黄尘妖」在自己场上只能有1只表侧表示存在。'),
(13839120, 'Yellow Gadget', '黄色小工具', 'イエロー・ガジェット', 'Effect Monster', 'Machine', 'EARTH', 4, 1200, 1200, '①：这张卡召唤·特殊召唤成功时才能发动。从卡组把1只「绿色零件」加入手卡。'),
(4542651, 'Yellow Luster Shield', '混沌护盾', 'カオス・シールド', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上存在的所有怪兽守备力上升300点。'),
(64749612, 'Yellow Ninja', '黄衣忍者', '黄色い忍者', 'Effect Monster', 'Warrior', 'WIND', 4, 1900, 1800, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转的场合才能发动。从手卡把1只4星以下的「忍者」怪兽表侧攻击表示或者里侧守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是「忍者」怪兽不能从额外卡组特殊召唤。'),
(53090623, 'Yellow-Bellied Oni', '黄血鬼', '黄血鬼', 'Effect Monster', 'Zombie', 'DARK', 4, 1000, 1000, '自己超量召唤成功时，这张卡可以从手卡特殊召唤。此外，1回合1次，把自己场上1个超量素材取除，选择场上1只超量怪兽才能发动。选择的怪兽的阶级下降1阶，攻击力下降300。'),
(40516623, 'Yoko-Zuna Sumo Spirit', '相扑魂 横纲', 'スモウ魂 YOKO－ZUNA', 'Spirit Monster', 'Warrior', 'WIND', 5, 2400, 1000, '①：这张卡召唤成功时才能发动。和自己的灵摆区域的卡相同纵列的对方怪兽全部送去墓地。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(3486020, 'Yoko, the Graceful Mayakashi', '丽之魔妖－妖狐', '麗の魔妖－妖狐', 'Synchro Monster', 'Zombie', 'FIRE', 9, 2900, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：「丽之魔妖-妖狐」在自己场上只能有1只表侧表示存在。 ②：这张卡在墓地存在，原本等级是11星的自己的同调怪兽被战斗或者对方的效果破坏的场合才能发动。从自己墓地把1只其他的不死族怪兽除外，这张卡特殊召唤。 ③：这张卡从墓地的特殊召唤成功的场合才能发动。选对方场上1只怪兽破坏。'),
(27750191, 'Yokotuner', '横纲犬', '横綱犬', 'Tuner Monster', 'Beast', 'EARTH', 1, 800, 600, '①：这张卡召唤成功时才能发动。从自己的手卡·墓地选1只调整特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(51534754, 'Yomi Ship', '通向黄泉的渡船', '黄泉へ渡る船', 'Effect Monster', 'Aqua', 'WATER', 3, 800, 1400, '①：这张卡被战斗破坏送去墓地的场合发动。把让这张卡破坏的怪兽破坏。'),
(57511992, 'Yorishiro of the Aqua', '海神的依代', '海神の依代', 'Effect Monster', 'Aqua', 'WATER', 4, 700, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只水属性怪兽为对象才能发动。从以下效果选1个适用。这个回合，自己不是水属性怪兽不能特殊召唤。 ●直到结束阶段，这张卡变成和作为对象的怪兽相同等级，当作同名卡使用。 ●场上有「海」存在的场合，作为对象的怪兽守备表示特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1张「海」为对象才能发动。那张卡加入手卡。'),
(17115745, 'Yormungarde', '尤蒙刚德', 'ヨルムンガルド', 'Normal Monster', 'Reptile', 'EARTH', 3, 1200, 900, '出现在神话世界的蛇。非常的长。'),
(27918963, 'Yosen Training Grounds', '修验的妖社', '修験の妖社', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「修验的妖社」的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，每次「妖仙兽」怪兽召唤·特殊召唤，给这张卡放置1个妖仙指示物。 ②：把这张卡的妖仙指示物任意数量取除才能发动。取除数量的以下效果适用。 ●1个：自己场上的「妖仙兽」怪兽的攻击力直到回合结束时上升300。 ●3个：从自己的卡组·墓地选1张「妖仙兽」卡加入手卡。'),
(79861914, 'Yosen Whirlwind', '妖仙大旋风', '妖仙大旋風', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '支付800基本分才能把这张卡发动。 ①：1回合1次，自己场上的表侧表示的「妖仙兽」怪兽回到手卡的场合，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。 ②：自己回合这张卡的①的效果没有适用的场合，那个回合的结束阶段这张卡破坏。'),
(85970321, 'Yosenju Izna', '妖仙兽 饭纲鞭', '妖仙獣 飯綱鞭', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 800, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。这个回合，在「妖仙兽」怪兽的召唤·特殊召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。 ②：自己场上有其他的「妖仙兽」怪兽存在的场合才能发动。自己从卡组抽1张。 ③：这张卡召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(65247798, 'Yosenju Kama 1', '妖仙兽 镰壹太刀', '妖仙獣 鎌壱太刀', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1600, 500, '①：这张卡召唤成功的场合才能发动。从手卡把「妖仙兽 镰壹太刀」以外的1只「妖仙兽」怪兽召唤。 ②：只在这张卡在场上表侧表示存在才有1次，自己场上有这张卡以外的「妖仙兽」怪兽存在的场合以对方场上1张表侧表示的卡为对象才能发动。那张卡回到持有者手卡。 ③：这张卡召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(92246806, 'Yosenju Kama 2', '妖仙兽 镰贰太刀', '妖仙獣 鎌弐太刀', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1800, 200, '①：这张卡召唤成功的场合才能发动。从手卡把「妖仙兽 镰贰太刀」以外的1只「妖仙兽」怪兽召唤。 ②：这张卡可以直接攻击。那次战斗给与对方的战斗伤害变成一半。 ③：这张卡召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(28630501, 'Yosenju Kama 3', '妖仙兽 镰叁太刀', '妖仙獣 鎌参太刀', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1500, 800, '「妖仙兽 镰叁太刀」的②的效果1回合只能使用1次。 ①：这张卡召唤成功的场合才能发动。从手卡把「妖仙兽 镰叁太刀」以外的1只「妖仙兽」怪兽召唤。 ②：这张卡以外的自己的「妖仙兽」怪兽给与对方战斗伤害时才能发动。从卡组把「妖仙兽 镰叁太刀」以外的1张「妖仙兽」卡加入手卡。 ③：这张卡召唤的回合的结束阶段发动。这张卡回到持有者手卡。');